// A Node port of crates/rules: the market contract's verdict rule, bond split, dispute window
// and request-extras check. tools/judge/vectors/rules.json, generated by the Rust crate itself
// (tools/judge/rules-vectors), proves the two agree case by case.
//
// The verdict comes from choices[0].message.content only: the parser below reads a chat
// completion the way the contract's serde_json does, with strict JSON, refused
// duplicate fields, and `reasoning_content` never read.

const UNPARSEABLE = "UNPARSEABLE";
export const ERR_NOT_COMPLETION = "the response is not a chat completion";
export const ERR_OTHER_MODEL = "the response names a different model";

// Rust's char::is_whitespace: the Unicode White_Space property (JavaScript's trim differs: it
// trims U+FEFF and keeps U+0085)
const WS = new Set([0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20, 0x85, 0xa0, 0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007, 0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000]);
function rustTrim(s) {
  const cps = [...s];
  let a = 0, b = cps.length;
  while (a < b && WS.has(cps[a].codePointAt(0))) a++;
  while (b > a && WS.has(cps[b - 1].codePointAt(0))) b--;
  return cps.slice(a, b).join("");
}

/** rules::verdict_of_answer: the first non-empty trimmed line, exactly one of three forms. */
export function verdictOfAnswer(content) {
  // str::lines: split on \n, and a line's trailing \r goes with it (trim removes it anyway)
  const line = content.split("\n").map(rustTrim).find((l) => l !== "") ?? "";
  return line === "VERDICT: TRUE" ? "TRUE" : line === "VERDICT: FALSE" ? "FALSE" : line === "VERDICT: INSUFFICIENT" ? "INSUFFICIENT" : UNPARSEABLE;
}

// ---------- strict JSON, as serde_json::from_slice reads it ----------

class JsonError extends Error {}

/** Parses bytes into a tree: {t:"obj", entries:[[key, node]]}, {t:"arr", items}, {t:"str", s, ok}, {t:"num"}, {t:"bool"}, {t:"null"}. */
export function parseStrict(bytes) {
  const b = bytes instanceof Uint8Array ? bytes : new TextEncoder().encode(String(bytes));
  let i = 0;
  const ws = () => { while (i < b.length && (b[i] === 0x20 || b[i] === 0x09 || b[i] === 0x0a || b[i] === 0x0d)) i++; };
  const fail = (m) => { throw new JsonError(m); };
  function value(depth) {
    ws();
    if (i >= b.length) fail("EOF");
    const c = b[i];
    // serde_json's recursion limit (128) guards typed values only; values it skips (IgnoredAny)
    // nest without a limit, and the typed path here is four levels deep, so no limit applies
    if (c === 0x7b || c === 0x5b) return c === 0x7b ? object(depth + 1) : array(depth + 1);
    if (c === 0x22) return string();
    if (c === 0x74) return lit("true", { t: "bool" });
    if (c === 0x66) return lit("false", { t: "bool" });
    if (c === 0x6e) return lit("null", { t: "null" });
    if (c === 0x2d || (c >= 0x30 && c <= 0x39)) return number();
    fail("expected value");
  }
  function lit(word, node) {
    for (let k = 0; k < word.length; k++) if (b[i + k] !== word.charCodeAt(k)) fail("expected ident");
    i += word.length;
    return node;
  }
  function number() {
    const start = i;
    if (b[i] === 0x2d) i++;
    if (b[i] === 0x30) { i++; if (b[i] >= 0x30 && b[i] <= 0x39) fail("invalid number"); }
    else if (b[i] >= 0x31 && b[i] <= 0x39) { while (b[i] >= 0x30 && b[i] <= 0x39) i++; }
    else fail("invalid number");
    let float = false;
    if (b[i] === 0x2e) { float = true; i++; if (!(b[i] >= 0x30 && b[i] <= 0x39)) fail("invalid number"); while (b[i] >= 0x30 && b[i] <= 0x39) i++; }
    if (b[i] === 0x65 || b[i] === 0x45) {
      float = true; i++;
      if (b[i] === 0x2b || b[i] === 0x2d) i++;
      if (!(b[i] >= 0x30 && b[i] <= 0x39)) fail("invalid number");
      while (b[i] >= 0x30 && b[i] <= 0x39) i++;
    }
    // a number serde_json skips (IgnoredAny) is never range-checked, and no field here is a number
    return { t: "num" };
  }
  function string() {
    i++; // opening quote
    const units = [];
    let ok = true; // false: holds a lone surrogate escape or invalid UTF-8
    let raw = [];
    const flushRaw = () => {
      if (!raw.length) return;
      const bytesOf = Uint8Array.from(raw);
      raw = [];
      let txt;
      try { txt = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(bytesOf); }
      catch { ok = false; txt = new TextDecoder("utf-8", { ignoreBOM: true }).decode(bytesOf); }
      for (let k = 0; k < txt.length; k++) units.push(txt.charCodeAt(k));
    };
    for (;;) {
      if (i >= b.length) fail("EOF while parsing a string");
      const c = b[i];
      if (c === 0x22) { i++; break; }
      if (c < 0x20) fail("control character");
      if (c !== 0x5c) { raw.push(c); i++; continue; }
      flushRaw();
      i++;
      const e = b[i++];
      const map = { 0x22: 0x22, 0x5c: 0x5c, 0x2f: 0x2f, 0x62: 0x08, 0x66: 0x0c, 0x6e: 0x0a, 0x72: 0x0d, 0x74: 0x09 };
      if (e in map) { units.push(map[e]); continue; }
      if (e !== 0x75) fail("invalid escape");
      const hex4 = () => {
        const h = Buffer.from(b.subarray(i, i + 4)).toString("latin1");
        if (!/^[0-9a-fA-F]{4}$/.test(h)) fail("invalid escape");
        i += 4;
        return parseInt(h, 16);
      };
      const u = hex4();
      if (u >= 0xd800 && u <= 0xdbff) {
        if (b[i] === 0x5c && b[i + 1] === 0x75) {
          const save = i;
          i += 2;
          const lo = hex4();
          if (lo >= 0xdc00 && lo <= 0xdfff) { units.push(u, lo); continue; }
          ok = false; i = save; units.push(u); continue;
        }
        ok = false; units.push(u); continue;
      }
      if (u >= 0xdc00 && u <= 0xdfff) { ok = false; units.push(u); continue; }
      units.push(u);
    }
    flushRaw();
    return { t: "str", s: String.fromCharCode(...units), ok };
  }
  function object(depth) {
    i++;
    const entries = [];
    ws();
    if (b[i] === 0x7d) { i++; return { t: "obj", entries }; }
    for (;;) {
      ws();
      if (b[i] !== 0x22) fail("key must be a string");
      const k = string();
      ws();
      if (b[i] !== 0x3a) fail("expected :");
      i++;
      entries.push([k, value(depth)]);
      ws();
      if (b[i] === 0x2c) { i++; ws(); if (b[i] === 0x7d) fail("trailing comma"); continue; }
      if (b[i] === 0x7d) { i++; return { t: "obj", entries }; }
      fail("expected , or }");
    }
  }
  function array(depth) {
    i++;
    const items = [];
    ws();
    if (b[i] === 0x5d) { i++; return { t: "arr", items }; }
    for (;;) {
      items.push(value(depth));
      ws();
      if (b[i] === 0x2c) { i++; ws(); if (b[i] === 0x5d) fail("trailing comma"); continue; }
      if (b[i] === 0x5d) { i++; return { t: "arr", items }; }
      fail("expected , or ]");
    }
  }
  const v = value(0);
  ws();
  if (i !== b.length) fail("trailing characters");
  return v;
}

// ---------- serde's derive over the parsed tree ----------

const bad = () => { throw new JsonError("invalid type"); };
const str = (n) => (n.t === "str" && n.ok ? n.s : bad());
const optStr = (n) => (n.t === "null" ? null : str(n));

/** A struct of named fields, from a map (unknown keys ignored, duplicates refused) or a sequence. */
function struct(n, fields) {
  const out = {};
  if (n.t === "obj") {
    for (const [k, v] of n.entries) {
      if (!k.ok) bad();
      const f = fields.find((x) => x.name === k.s);
      if (!f) continue;
      if (k.s in out) throw new JsonError(`duplicate field ${k.s}`);
      out[k.s] = f.read(v);
    }
    for (const f of fields) if (!(f.name in out)) out[f.name] = f.missing();
    return out;
  }
  if (n.t === "arr") {
    for (let k = 0; k < fields.length; k++) {
      const f = fields[k];
      if (k < n.items.length) out[f.name] = f.read(n.items[k]);
      else if (f.hasDefault) out[f.name] = f.missing();
      else bad(); // invalid length
    }
    if (n.items.length > fields.length) bad();
    return out;
  }
  return bad();
}
const MESSAGE = [{ name: "content", read: optStr, missing: () => null }];
const CHOICE = [{ name: "message", read: (n) => (n.t === "null" ? null : struct(n, MESSAGE)), missing: () => null }];
const COMPLETION = [
  { name: "model", read: optStr, missing: () => null },
  { name: "choices", read: (n) => (n.t === "arr" ? n.items.map((x) => struct(x, CHOICE)) : bad()), missing: () => [], hasDefault: true },
];

/** rules::verdict_of_response: { ok: verdict } or { err: message }. */
export function verdictOfResponse(bytes, requestedModel) {
  let c;
  try { c = struct(parseStrict(bytes), COMPLETION); }
  catch (e) { if (e instanceof JsonError) return { err: ERR_NOT_COMPLETION }; throw e; }
  if (c.model !== requestedModel) return { err: ERR_OTHER_MODEL };
  const content = c.choices[0]?.message?.content;
  return { ok: content == null ? UNPARSEABLE : verdictOfAnswer(content) };
}

// ---------- money ----------

/** rules::split_bonds: stakes are [side, bond] in posting order, bonds BigInt. Returns [pay[], treasury]. */
export function splitBonds(stakes, outcome) {
  let won = 0n, lost = 0n;
  for (const [side, amt] of stakes) { if (side === outcome) won += amt; else lost += amt; }
  if (won === 0n) return [stakes.map(() => 0n), lost];
  const pay = stakes.map(([side, amt]) => (side === outcome ? amt + (lost * amt) / won : 0n));
  const paid = pay.reduce((a, x) => a + x, 0n);
  let first = stakes.findIndex(([side, amt]) => side === outcome && amt > 0n);
  if (first < 0) first = 0;
  pay[first] += won + lost - paid;
  return [pay, 0n];
}

/** rules::window_secs */
export function windowSecs(tiers, topSecs, openInterest) {
  const t = tiers.find(([below]) => openInterest < below);
  return t ? t[1] : topSecs;
}

/** rules::tiers_ok */
export function tiersOk(tiers, topSecs) {
  if (tiers.length > 8 || topSecs === 0) return false;
  let last = [0n, 1];
  for (const t of tiers) {
    if (t[0] <= last[0] || t[1] < last[1] || t[1] > topSecs) return false;
    last = t;
  }
  return true;
}

/** rules::extras_ok: the inside of a JSON object, which may not touch the fixed fields. */
export function extrasOk(extras) {
  if (extras === "") return true;
  const bytes = new TextEncoder().encode(extras);
  if (bytes.length > 512) return false;
  let tree;
  try { tree = parseStrict(new TextEncoder().encode(`{${extras}}`)); } catch { return false; }
  if (tree.t !== "obj") return false;
  const keys = new Set();
  for (const [k] of tree.entries) { if (!k.ok) return false; keys.add(k.s); }
  return !["model", "messages", "temperature", "stream", "n"].some((k) => keys.has(k));
}
